<script lang="ts">import {createTabsController} from "@weiui/core";import {normalizeSvelteProps} from "./internal.js";type Item={value:string;label?:string;content?:string;disabled?:boolean};let {items=[],value=$bindable(""),orientation="horizontal",id="wui-tabs"}=$props<{items?:Item[];value?:string;orientation?:"horizontal"|"vertical";id?:string}>();const controller=createTabsController({id,defaultValue:value,orientation,onValueChange:next=>value=next});let state=$state(controller.getState());$effect(()=>{const off=controller.subscribe(next=>state=next);return off});$effect(()=>{if(value!==state.value)controller.store.setState({value})});function p(kind:"root"|"list"|"trigger"|"content",item?:Item){state;return normalizeSvelteProps(kind==="root"?controller.getRootProps():kind==="list"?controller.getListProps():kind==="trigger"?controller.getTriggerProps(item!.value,item!.disabled):controller.getContentProps(item!.value))}</script><div {...p("root")} class="wui-tabs"><div {...p("list")} class="wui-tabs__list">{#each items as item (item.value)}<button {...p("trigger",item)} class="wui-tabs__trigger">{item.label??item.value}</button>{/each}</div>{#each items as item (item.value)}<div {...p("content",item)} class="wui-tabs__content">{item.content??""}</div>{/each}</div>
